(()=>{
const en=document.documentElement.lang==='en',t=(zh,english)=>en?english:zh,$=id=>document.getElementById(id),data=window.GreenGoBusRoutes;
if(!data)return;
const card=document.createElement('section');card.className='route-card';card.id='busFavourites';card.innerHTML=`<p class="eyebrow">SAVED BUS ROUTES / NO API CALLS</p><h3>${t('常用公交路线','Saved bus routes')}</h3><div class="two-col"><label>${t('线路','Bus line')}<select id="savedBusLine"></select></label><label>${t('方向／站序','Direction / stop sequence')}<select id="savedBusDirection"></select></label><label>${t('上车站','Boarding stop')}<select id="savedBusBoard"></select></label><label>${t('下车站','Alighting stop')}<select id="savedBusAlight"></select></label></div><p id="savedBusStatus" role="status"></p><button id="useSavedBus" type="button" class="primary">${t('确认此线路，检查天气','Confirm this line & check weather')}</button><details><summary>${t('查看保存的完整站序','View saved stop sequence')}</summary><ol id="savedBusStops"></ol></details><p>${t('运营商官网站序快照：2026-11-08 获取，对照 11月8日和9日。仅为静态合并站序，不含实时班次；部分班次可能截短或跳过站点。X21 的 Merry Hill 延长段仅部分周日班次运行。切换不调用 TransportAPI。','Operator stop-order snapshot retrieved 8 Nov 2026, checked against 8 and 9 Nov. Static combined stop sequences only; trips may terminate early or omit stops. X21 extends to Merry Hill on some Sunday trips. Switching makes no TransportAPI calls.')}</p><a id="savedBusSource" target="_blank" rel="noopener">${t('查看运营商当前线路说明 ↗','Check current operator route information ↗')}</a>`;
$('live-transit').append(card);
const sources={X20:'https://nxbus.co.uk/west-midlands/services-timetables/x20-birmingham-bromsgrove',X21:'https://westmidlandsbus.co.uk/west-midlands/services-timetables/x21-birmingham-bartley-green',X22:'https://westmidlandsbus.co.uk/west-midlands/services-timetables/x22-birmingham-bartley-green'};
for(const line of data.lines)$('savedBusLine').add(new Option(line.line,line.line));
const key='greengo-saved-bus-v1';let saved=null;try{saved=JSON.parse(localStorage.getItem(key)||'null');}catch{}
if(saved&&data.lines.some(l=>l.line===saved.line))$('savedBusLine').value=saved.line;
function patterns(){return data.lines.find(l=>l.line===$('savedBusLine').value).patterns;}
function pattern(){return patterns().find(p=>p.id===$('savedBusDirection').value)||patterns()[0];}
function persist(){try{localStorage.setItem(key,JSON.stringify({line:$('savedBusLine').value,pattern:pattern().id,board:$('savedBusBoard').value,alight:$('savedBusAlight').value}));}catch{}}
function status(){const p=pattern(),a=p.stops.findIndex(s=>s.id===$('savedBusBoard').value),b=p.stops.findIndex(s=>s.id===$('savedBusAlight').value);const valid=a>=0&&b>a;$('useSavedBus').disabled=!valid;$('savedBusStatus').textContent=valid?`${$('savedBusLine').value} · ${p.stops[a].name} → ${p.stops[b].name} · ${b-a} ${t('段站间衔接；需核对具体班次停站','stop intervals; verify the individual trip')}`:t('下车站须在上车站之后，请检查方向。','Alighting must follow boarding; check the direction.');persist();}
function stops(){const p=pattern();for(const id of ['savedBusBoard','savedBusAlight']){$(id).replaceChildren();for(const s of p.stops)$(id).add(new Option(s.name+' · '+s.id,s.id));}$('savedBusAlight').selectedIndex=Math.max(1,p.stops.findIndex(s=>s.name==='University North Gate'));if(saved?.pattern===p.id){if(p.stops.some(s=>s.id===saved.board))$('savedBusBoard').value=saved.board;if(p.stops.some(s=>s.id===saved.alight))$('savedBusAlight').value=saved.alight;}const list=$('savedBusStops');list.replaceChildren();for(const s of p.stops){const li=document.createElement('li');li.textContent=s.name+' · '+s.id+(s.allJourneys?'':t(' · 部分班次',' · some trips'));list.append(li);}$('savedBusSource').href=sources[$('savedBusLine').value];status();}
function directions(){const select=$('savedBusDirection');select.replaceChildren();for(const p of patterns())select.add(new Option(p.origin+' → '+p.destination,p.id));const preferred=patterns().find(p=>p.id===saved?.pattern)||patterns().find(p=>p.direction==='O');if(preferred)select.value=preferred.id;stops();}
$('savedBusLine').onchange=()=>{saved=null;directions();};$('savedBusDirection').onchange=()=>{saved=null;stops();};$('savedBusBoard').onchange=$('savedBusAlight').onchange=status;
$('useSavedBus').onclick=()=>{const p=pattern(),stop=p.stops.find(s=>s.id===$('savedBusAlight').value);window.dispatchEvent(new CustomEvent('greengo:mode-selected',{detail:{mode:'bus'}}));$('campusStart').value='bus';$('campusBus').value=stop.name+', Birmingham';$('campusStart').dispatchEvent(new Event('change'));$('campusBus').dispatchEvent(new Event('input'));$('campusModeNotice').textContent=$('savedBusLine').value+' · '+stop.name+' · '+t('使用保存站点衔接步行；尚未核验该日期具体班次。','Walking connection from saved stop; the selected date’s individual service is unverified.');if(window.GreenGoTravelFlow)window.GreenGoTravelFlow.show('weather');else document.querySelector('#arrivalFlow nav button:nth-child(3)').click();};
const css=document.createElement('style');css.textContent='#busFavourites{margin-top:24px}#busFavourites details{margin-top:18px}#busFavourites>p:not(.eyebrow),#savedBusSource{font-size:11px;line-height:1.6}#savedBusStops{max-height:300px;overflow:auto;font-size:12px;line-height:2}#savedBusStatus{font-size:13px!important;color:#173e3c}';document.head.append(css);directions();
})();
